export type createDemoSessionResponse201 = {
  data: Session
  status: 201
}

export type createDemoSessionResponse404 = {
  data: NotFoundResponse
  status: 404
}

export type createDemoSessionResponse422 = {
  data: UnprocessableResponse
  status: 422
}

export type createDemoSessionResponse429 = {
  data: TooManyRequestsResponse
  status: 429
}

export type createDemoSessionResponseSuccess = (createDemoSessionResponse201) & {
  headers: Headers;
};
export type createDemoSessionResponseError = (createDemoSessionResponse404 | createDemoSessionResponse422 | createDemoSessionResponse429) & {
  headers: Headers;
};

export type createDemoSessionResponse = (createDemoSessionResponseSuccess | createDemoSessionResponseError)

export const getCreateDemoSessionUrl = () => {




  return `/v1/demo/sessions`
}

/**
 * Returns 404 unless DEMO_MODE is enabled. Rate-limited per IP.
 * @summary Start a trial session for a role (demo mode only)
 */
export const createDemoSession = async (createDemoSessionRequest: CreateDemoSessionRequest, options?: RequestInit): Promise<createDemoSessionResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
const res = await fetch(getCreateDemoSessionUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(createDemoSessionRequest)
  }
)


  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: createDemoSessionResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as createDemoSessionResponse
}



